(ARRAY['kcet','neet-ug','jee-main','jee-advanced','comedk','scholarship'],'Chemistry','Class 11-12',2026,'Equilibrium','','medium','single','The pH of 0.001 M NaOH solution is:','[{"id": "a", "text": "3"}, {"id": "b", "text": "10"}, {"id": "c", "text": "11"}, {"id": "d", "text": "12"}]'::jsonb,'"c"'::jsonb,'[OH-] = 10^-3, so pOH = 3. pH = 14 - 3 = 11.','["Find pOH from [OH-].", "pOH = -log(0.001) = 3.", "pH = 14 - pOH."]'::jsonb,'Original NCERT-aligned question — Study at Bangalore (AI-assisted draft, pending teacher review)',false,'verified','NCERT Chemistry XI Ch 7'),
